import React, { useContext } from "react";
import { GlobalContext } from "../../context/GlobalState";
import Menu from "../layout/Menu";
import Header from "../layout/Header";
import BreadCrumb from "../sections/BreadCrumb";
import LoaderScreen from "../../pages/LoaderScreen";
import { useForm } from "react-hook-form";
import Swal from "sweetalert2";

const PickSupermarket = () => {
  const { isLoading } = useContext(GlobalContext);

  const menu = {
    title: "Supermarket selection",
    subTitle: "Choose",
    links: [
      // { url: "/messages", text: "Messages", icon: <MessageSquare size={13} /> },
      // { url: "/profile", text: "Profile", icon: <User size={13} /> },
    ],
  };

  const supermarkets = [
    { name: "Carrefour Kenya", img: "" },
    { name: "Quickmart", img: "" },
    { name: "Cleanshelf", img: "" },
    { name: "Eastmatt", img: "" },
    { name: "Naivas", img: "" },
    { name: "Peter Mulei", img: "" },
  ];

  return (
    <>
      {isLoading && (
        <>
          <div className="load_screen">
            <LoaderScreen text="Loading your profile info" />
          </div>
        </>
      )}
      {!isLoading && (
        <>
          <Header />
          <div className="page">
            <div className="container">
              <Menu menu={menu} />
              <BreadCrumb />
              <div className="row">
                <div className="col-md-8 col-12">
                  <div className="supermarket-list">
                    <label></label>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </>
      )}
    </>
  );
};

export default PickSupermarket;
